// features/counter/counterSlice.js
import { createSlice } from "@reduxjs/toolkit";

const counterSlice = createSlice({
  name: "counter",
  initialState: { value: 0 },
  reducers: {
    increment: (state) => { state.value += 1; },       // Immer makes this safe
    addBy: (state, action) => { state.value += action.payload; },
    reset: () => ({ value: 0 }),
  },
});
export const { increment, addBy, reset } = counterSlice.actions;
export default counterSlice.reducer;

// app/store.js
import { configureStore } from "@reduxjs/toolkit";
import counter from "../features/counter/counterSlice";
export const store = configureStore({ reducer: { counter } });

// main.jsx
import { Provider } from "react-redux";
// <Provider store={store}><App /></Provider>

// Counter.jsx
import { useSelector, useDispatch } from "react-redux";
import { increment, addBy } from "./counterSlice";

export function Counter() {
  const value = useSelector((s) => s.counter.value);
  const dispatch = useDispatch();
  return (
    <>
      <p>{value}</p>
      <button onClick={() => dispatch(increment())}>+1</button>
      <button onClick={() => dispatch(addBy(5))}>+5</button>
    </>
  );
}

// A tiny store showing the same Redux ideas: actions -> reducer -> state
const StoreCtx = createContext(null);

function todosReducer(state, action) {
  switch (action.type) {
    case "todos/added": return [...state, { id: state.length + 1, text: action.payload, done: false }];
    case "todos/toggled": return state.map((t) => (t.id === action.payload ? { ...t, done: !t.done } : t));
    default: return state;
  }
}

function StoreProvider({ children }) {
  const [state, dispatch] = useReducer(todosReducer, [{ id: 1, text: "Read about Redux", done: false }]);
  return <StoreCtx.Provider value={{ state, dispatch }}>{children}</StoreCtx.Provider>;
}
const useStore = () => useContext(StoreCtx);

function TodoList() {
  const { state, dispatch } = useStore();
  return (
    <ul>
      {state.map((t) => (
        <li key={t.id} onClick={() => dispatch({ type: "todos/toggled", payload: t.id })}
          style={{ cursor: "pointer", textDecoration: t.done ? "line-through" : "none" }}>{t.text}</li>
      ))}
    </ul>
  );
}
function AddTodo() {
  const { dispatch } = useStore();
  const [text, setText] = useState("");
  return (
    <form onSubmit={(e) => { e.preventDefault(); if (text) dispatch({ type: "todos/added", payload: text }); setText(""); }}>
      <input value={text} onChange={(e) => setText(e.target.value)} placeholder="New todo" />
      <button>Add</button>
    </form>
  );
}
function Counter() {
  const { state } = useStore();
  return <small>{state.filter((t) => !t.done).length} remaining</small>;
}

function App() {
  return (
    <StoreProvider>
      <div style={{ fontFamily: "sans-serif", padding: 12 }}>
        <AddTodo /><TodoList /><Counter />
      </div>
    </StoreProvider>
  );
}

topics.description:
### createAsyncThunk

For async work (API calls) inside Redux, RTK provides `createAsyncThunk`. It dispatches three actions automatically: `pending`, `fulfilled` and `rejected`. You handle them in `extraReducers`.

```js
export const fetchUsers = createAsyncThunk("users/fetch", async (_, { rejectWithValue }) => {
  const res = await fetch("/api/users");
  if (!res.ok) return rejectWithValue("Failed");
  return res.json();
});
```

State shape: `{ items: [], status: "idle" | "loading" | "succeeded" | "failed", error: null }`.

### RTK Query

Writing thunks, loading flags and caching by hand is repetitive. **RTK Query** is a data fetching and caching tool included in Redux Toolkit. You define an **API slice** with endpoints and it generates hooks.

```js
export const api = createApi({
  reducerPath: "api",
  baseQuery: fetchBaseQuery({ baseUrl: "/api" }),
  tagTypes: ["Post"],
  endpoints: (b) => ({
    getPosts: b.query({ query: () => "posts", providesTags: ["Post"] }),
    addPost: b.mutation({
      query: (body) => ({ url: "posts", method: "POST", body }),
      invalidatesTags: ["Post"],
    }),
  }),
});
export const { useGetPostsQuery, useAddPostMutation } = api;
```

### Features

- Automatic caching, deduplication and refetching.
- **Tags** for cache invalidation: a mutation invalidates tags, related queries refetch.
- Generated hooks with `isLoading`, `isFetching`, `error`, `data`.
- Optimistic updates via `onQueryStarted`.
- Polling, conditional `skip`, code-splitting with `injectEndpoints`.

### RTK Query vs TanStack Query

Both solve server state. Choose RTK Query if you already use Redux; otherwise TanStack Query is lighter and framework-agnostic.

