import { configureStore } from "@reduxjs/toolkit";
import { createApi, fetchBaseQuery } from "@reduxjs/toolkit/query/react";

export const api = createApi({
  reducerPath: "api",
  baseQuery: fetchBaseQuery({ baseUrl: "/api" }),
  tagTypes: ["Post"],
  endpoints: (build) => ({
    getPosts: build.query({ query: () => "posts", providesTags: ["Post"] }),
    addPost: build.mutation({
      query: (body) => ({ url: "posts", method: "POST", body }),
      invalidatesTags: ["Post"],
    }),
  }),
});
export const { useGetPostsQuery, useAddPostMutation } = api;

export const store = configureStore({
  reducer: { [api.reducerPath]: api.reducer },
  middleware: (getDefault) => getDefault().concat(api.middleware),
});

// Component
function Posts() {
  const { data = [], isLoading, error } = useGetPostsQuery();
  const [addPost, { isLoading: saving }] = useAddPostMutation();
  if (isLoading) return <p>Loading...</p>;
  if (error) return <p>Failed</p>;
  return (
    <>
      <ul>{data.map((p) => <li key={p.id}>{p.title}</li>)}</ul>
      <button disabled={saving} onClick={() => addPost({ title: "Hello" })}>Add</button>
    </>
  );
}

const { useSyncExternalStore } = React;

function createStore(initializer) {
  let state;
  const listeners = new Set();
  const set = (partial) => {
    const next = typeof partial === "function" ? partial(state) : partial;
    state = { ...state, ...next };
    listeners.forEach((l) => l());
  };
  const get = () => state;
  state = initializer(set, get);
  const subscribe = (l) => { listeners.add(l); return () => listeners.delete(l); };
  return function useStore(selector = (s) => s) {
    return useSyncExternalStore(subscribe, () => selector(state));
  };
}

const useCart = createStore((set) => ({
  items: [],
  add: (name) => set((s) => ({ items: [...s.items, name] })),
  clear: () => set({ items: [] }),
}));

function Badge() {
  const n = useCart((s) => s.items.length);
  return <b>Cart: {n}</b>;
}
function Buttons() {
  const add = useCart((s) => s.add);
  const clear = useCart((s) => s.clear);
  return (
    <>
      <button onClick={() => add("Item")}>Add item</button>
      <button onClick={clear}>Clear</button>
    </>
  );
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Badge /> <Buttons />
    </div>
  );
}

import { create } from "zustand";
import { persist, devtools } from "zustand/middleware";

export const useTheme = create(
  devtools(
    persist(
      (set) => ({
        mode: "light",
        toggle: () => set((s) => ({ mode: s.mode === "light" ? "dark" : "light" })),
      }),
      { name: "theme-storage" }
    )
  )
);

function ThemeButton() {
  const mode = useTheme((s) => s.mode);
  const toggle = useTheme((s) => s.toggle);
  return <button onClick={toggle}>Mode: {mode}</button>;
}

const { useSyncExternalStore } = React;

function atom(initial) {
  let value = initial;
  const subs = new Set();
  return {
    get: () => value,
    set: (v) => { value = typeof v === "function" ? v(value) : v; subs.forEach((s) => s()); },
    subscribe: (s) => { subs.add(s); return () => subs.delete(s); },
  };
}
function useAtom(a) {
  const v = useSyncExternalStore(a.subscribe, a.get);
  return [v, a.set];
}

const countAtom = atom(1);
const nameAtom = atom("Asha");

function Count() {
  const [c, setC] = useAtom(countAtom);
  console.log("Count rendered");
  return <button onClick={() => setC((x) => x + 1)}>count: {c}</button>;
}
function Name() {
  const [n, setN] = useAtom(nameAtom);
  console.log("Name rendered");
  return <input value={n} onChange={(e) => setN(e.target.value)} />;
}

function App() {
  return (
    <div style={{ fontFamily: "sans-serif", padding: 12 }}>
      <Count /> <Name />
      <p><small>Typing in the input does not re-render Count (see console).</small></p>
    </div>
  );
}

// Where should this state live?
//
// Only one component needs it?            -> useState
// A few siblings need it?                 -> lift to common parent
// Many distant components, rarely changes -> Context (theme, auth, locale)
// Many components, changes often          -> Zustand / Jotai / Redux Toolkit
// It comes from a backend                 -> TanStack Query / RTK Query
// It should survive refresh/be shareable  -> URL (search params)
// It is a form                            -> React Hook Form
